using System.ComponentModel;
using System.Net;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the chat client through MEAI ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Create tool instances ---
var notebook = new ResearchNotebook();
var searcher = new WebSearcher();

// --- Build the research agent ---
var agent = new AIAgentBuilder()
    .AddChatClient(chatClient)
    .AddTool(AIFunctionFactory.Create(
        searcher.SearchAsync,
        nameof(WebSearcher.SearchAsync),
        "Search the web for a query and return a page of results. " +
        "Use different queries to get diverse information."))
    .AddTool(AIFunctionFactory.Create(
        notebook.AddNote,
        nameof(ResearchNotebook.AddNote),
        "Save a research note with a title and body. " +
        "Use this to record key findings before summarizing."))
    .AddTool(AIFunctionFactory.Create(
        notebook.GetAllNotes,
        nameof(ResearchNotebook.GetAllNotes),
        "Retrieve all saved research notes."))
    .Build();

// --- Get topic from user ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System,
        """
        You are a thorough research agent. When given a topic:
        1. Search the web with 2-3 different queries to gather diverse information.
        2. Take notes on each significant finding using the note-taking tool.
        3. After gathering enough information, retrieve all your notes.
        4. Provide a well-structured summary with key findings, citing the sources you found.
        Be concise but comprehensive. Always take notes before summarizing.
        """),
    new(ChatRole.User,
        $"Research the following topic and provide a detailed summary: {topic}"),
};

var options = new ChatClientAgentRunOptions
{
    MaxIterations = 15,
};

// --- Stream the agent response ---
await foreach (var update in agent.InvokeStreamingAsync(messages, options))
{
    if (update.Text is { Length: > 0 } text)
    {
        Console.Write(text);
    }
}

Console.WriteLine("\n\n📝 Notes collected during research:");
Console.WriteLine(new string('─', 50));
foreach (var note in notebook.Notes)
{
    Console.WriteLine($"  • {note.Title}");
    Console.WriteLine($"    {note.Body}\n");
}

// ──────────────────────────────────────────────
// Tool: Web Search
// ──────────────────────────────────────────────
sealed class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for a query and return relevant snippets.")]
    public async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            // Extract result snippets from DuckDuckGo HTML results
            var results = ParseDuckDuckGoResults(html);

            if (results.Count == 0)
                return $"No results found for '{query}'.";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: {query}\n");
            for (var i = 0; i < Math.Min(results.Count, 5); i++)
            {
                sb.AppendLine($"[{i + 1}] {results[i].Title}");
                sb.AppendLine($"    {results[i].Snippet}");
                sb.AppendLine($"    Source: {results[i].Url}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    private static List<SearchResult> ParseDuckDuckGoResults(string html)
    {
        var results = new List<SearchResult>();

        // Parse result blocks from DuckDuckGo HTML
        var resultSpans = html.Split("class=\"result__a\"",
            StringSplitOptions.RemoveEmptyEntries);

        for (var i = 1; i < resultSpans.Length && results.Count < 5; i++)
        {
            var block = resultSpans[i];

            var title = ExtractBetween(block, ">", "</a>")?.Trim();
            var snippet = ExtractSnippet(block);
            var url = ExtractBetween(block, "href=\"", "\"");

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new SearchResult
                {
                    Title = StripHtml(title),
                    Snippet = StripHtml(snippet ?? "No snippet available."),
                    Url = url ?? "unknown",
                });
            }
        }

        return results;
    }

    private static string? ExtractSnippet(string block)
    {
        var snippetStart = block.IndexOf("class=\"result__snippet\"",
            StringComparison.Ordinal);
        if (snippetStart < 0) return null;

        var contentStart = block.IndexOf('>', snippetStart) + 1;
        var contentEnd = block.IndexOf("</", contentStart, StringComparison.Ordinal);

        return contentStart > 0 && contentEnd > contentStart
            ? block[contentStart..contentEnd]
            : null;
    }

    private static string? ExtractBetween(string text, string start, string end)
    {
        var s = text.IndexOf(start, StringComparison.Ordinal);
        if (s < 0) return null;
        s += start.Length;
        var e = text.IndexOf(end, s, StringComparison.Ordinal);
        return e < 0 ? null : text[s..e];
    }

    private static string StripHtml(string html)
    {
        var sb = new StringBuilder();
        var inTag = false;
        foreach (var c in html)
        {
            switch (c)
            {
                case '<': inTag = true; break;
                case '>': inTag = false; break;
                default:
                    if (!inTag) sb.Append(c);
                    break;
            }
        }
        return WebUtility.HtmlDecode(sb.ToString().Trim());
    }

    private sealed class SearchResult
    {
        public string Title { get; init; } = "";
        public string Snippet { get; init; } = "";
        public string Url { get; init; } = "";
    }
}

// ──────────────────────────────────────────────
// Tool: Research Notebook
// ──────────────────────────────────────────────
sealed class ResearchNotebook
{
    private readonly List<Note> _notes = [];

    public IReadOnlyList<Note> Notes => _notes;

    [Description("Save a research note with a title and body.")]
    public string AddNote(
        [Description("Short title for the note")] string title,
        [Description("Detailed content of the note")] string body)
    {
        _notes.Add(new Note(title, body));
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note '{title}' saved successfully. Total notes: {_notes.Count}";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"Research Notes ({_notes.Count} total):\n");
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"--- Note {i + 1}: {_notes[i].Title} ---");
            sb.AppendLine(_notes[i].Body);
            sb.AppendLine();
        }

        return sb.ToString();
    }

    public sealed record Note(string Title, string Body);
}

