using System.Net;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Create tool instances ---
var notebook = new ResearchNotebook();
var searcher = new WebSearcher();

var tools = new AITool[]
{
    AIFunctionFactory.Create(searcher.SearchAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetAllNotes),
};

// --- Build the chat client through MEAI with function-invoking middleware ---
IChatClient chatClient = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation(opts => opts.MaximumIterationsPerRequest = 15)
    .Build();

// --- Build the research agent ---
const string instructions =
    """
    You are a thorough research agent. When given a topic:
    1. Search the web with 2-3 different queries to gather diverse information.
    2. Take notes on each significant finding using the note-taking tool.
    3. After gathering enough information, retrieve all your notes.
    4. Provide a well-structured summary with key findings, citing sources.
    Be concise but comprehensive. Always take notes before summarizing.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches a topic using web search and note-taking tools.",
    tools: tools);

// --- Get topic from user ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Create a session and run the agent ---
var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a detailed summary: {topic}",
    session,
    runOptions))
{
    if (update.Text is { Length: > 0 } text)
    {
        Console.Write(text);
    }
}

Console.WriteLine("\n\n📝 Notes collected during research:");
Console.WriteLine(new string('─', 50));
foreach (var note in notebook.Notes)
{
    Console.WriteLine($"  • {note.Title}");
    Console.WriteLine($"    {note.Body}\n");
}

