94.     {
95.         DefaultRequestHeaders =
96.         {
97.             { "User-Agent", "ResearchAgent/1.0" },
98.             { "Accept", "text/html" },
99.         },
100.         Timeout = TimeSpan.FromSeconds(15),
101.     };
