103.     [Description("Search the web for a query and return relevant snippets.")]
104.     public async Task<string> SearchAsync(
105.         [Description("The search query")] string query)
106.     {
107.         Console.WriteLine($"  🌐 Searching: \"{query}\"");
108. 
109.         try
110.         {
111.             var encoded = WebUtility.UrlEncode(query);
112.             var url = $"https://html.duckduckgo.com/html/?q={encoded}";
113.             var html = await Http.GetStringAsync(url);
114. 
115.             // Extract result snippets from DuckDuckGo HTML results
116.             var results = ParseDuckDuckGoResults(html);
117. 
118.             if (results.Count == 0)
119.                 return $"No results found for '{query}'.";
120. 
121.             var sb = new StringBuilder();
122.             sb.AppendLine($"Search results for: {query}\n");
123.             for (var i = 0; i < Math.Min(results.Count, 5); i++)
124.             {
125.                 sb.AppendLine($"[{i + 1}] {results[i].Title}");
126.                 sb.AppendLine($"    {results[i].Snippet}");
127.                 sb.AppendLine($"    Source: {results[i].Url}");
128.                 sb.AppendLine();
129.             }
130. 
131.             return sb.ToString();
132.         }
133.         catch (Exception ex)
134.         {
135.             return $"Search failed for '{query}': {ex.Message}";
136.         }
137.     }
138. 
139.     private static List<SearchResult> ParseDuckDuckGoResults(string html)
140.     {
141.         var results = new List<SearchResult>();
142. 
143.         // Parse result blocks from DuckDuckGo HTML
144.         var resultSpans = html.Split("class=\"result__a\"",
145.             StringSplitOptions.RemoveEmptyEntries);
146. 
147.         for (var i = 1; i < resultSpans.Length && results.Count < 5; i++)
148.         {
149.             var block = resultSpans[i];
150. 
151.             var title = ExtractBetween(block, ">", "</a>")?.Trim();
152.             var snippet = ExtractSnippet(block);
153.             var url = ExtractBetween(block, "href=\"", "\"");
154. 
155.             if (!string.IsNullOrWhiteSpace(title))
156.             {
157.                 results.Add(new SearchResult
158.                 {
159.                     Title = StripHtml(title),
160.                     Snippet = StripHtml(snippet ?? "No snippet available."),
161.                     Url = url ?? "unknown",
162.                 });
163.             }
164.         }
165. 
166.         return results;
167.     }
168. 
169.     private static string? ExtractSnippet(string block)
170.     {
171.         var snippetStart = block.IndexOf("class=\"result__snippet\"",
172.             StringComparison.Ordinal);
173.         if (snippetStart < 0) return null;
174. 
175.         var contentStart = block.IndexOf('>', snippetStart) + 1;
176.         var contentEnd = block.IndexOf("</", contentStart, StringComparison.Ordinal);
177. 
178.         return contentStart > 0 && contentEnd > contentStart
179.             ? block[contentStart..contentEnd]
180.             : null;
181.     }
182. 
183.     private static string? ExtractBetween(string text, string start, string end)
184.     {
185.         var s = text.IndexOf(start, StringComparison.Ordinal);
186.         if (s < 0) return null;
187.         s += start.Length;
188.         var e = text.IndexOf(end, s, StringComparison.Ordinal);
189.         return e < 0 ? null : text[s..e];
190.     }
