192.     private static string StripHtml(string html)
193.     {
194.         var sb = new StringBuilder();
195.         var inTag = false;
196.         foreach (var c in html)
197.         {
198.             switch (c)
199.             {
200.                 case '<': inTag = true; break;
201.                 case '>': inTag = false; break;
202.                 default:
203.                     if (!inTag) sb.Append(c);
204.                     break;
205.             }
206.         }
207.         return WebUtility.HtmlDecode(sb.ToString().Trim());
208.     }
